OLD_MODELS = DATA["old_models"]
MODELS = DATA["models"]
SPECIMENS = DATA["specimens"]
SCALES = DATA["scales"]
BAND_VALUES = np.asarray(DATA["band_values"], dtype=float)
FINE_DELTA = np.asarray(DATA["fine_delta"], dtype=float)
FINE_SUMMARY = np.asarray(DATA["fine_summary"], dtype=float)
AGGREGATE_DELTA = np.asarray(DATA["aggregate_delta"], dtype=float)
AGGREGATE_SUMMARY = np.asarray(DATA["aggregate_summary"], dtype=float)
DIRECT_DELTA = np.asarray(DATA["direct_delta"], dtype=float)
DIRECT_SUMMARY = np.asarray(DATA["direct_summary"], dtype=float)
METRICS = ["mean_q_B4_B5", "mean_q_B1_B2", "ordinary_PCC_official_support"]
DIRECT_CONTRASTS = ["old_local_minus_old_standard", "local_minus_non_neighbour"]
# === END DATA SECTOR ===

plt.rcParams.update({
    "pdf.fonttype":42, "ps.fonttype":42, "axes.unicode_minus":False,
    "font.family":"sans-serif", "font.sans-serif":["Arial"],
    "font.size":7.0, "font.weight":"regular", "axes.labelsize":7.0,
    "axes.titlesize":8.0, "xtick.labelsize":7.0, "ytick.labelsize":7.0,
})
W,H=180.0,210.0
PAPER="#FFFFFF" # L1-PIL dominant exact page color; author-required difference zero.
INK="#262522" # L1-PIL exact repeated ink cluster in v95.
MID="#77736D" # L1 baseline neutral comparison glyphs.
RULE="#D7D2C9" # L1 repeated atlas rules; L2 recessive hairline class.
TEAL="#1D6872" # L1-PIL exact reference fill at (589,601), 2904 exact pixels.
BRICK="#A44738" # L1 approved baseline negative endpoint; same hue class.
CREAM="#F2E4C7" # L1 approved absolute-score zero transition, not difference zero.
Q_CMAP=LinearSegmentedColormap.from_list("absolute",[BRICK,CREAM,"#D9D7C8",TEAL],N=256)
D_CMAP=LinearSegmentedColormap.from_list("signed",[BRICK,PAPER,TEAL],N=257)
Q_NORM=TwoSlopeNorm(vmin=-.15,vcenter=0,vmax=.82)
F_NORM=TwoSlopeNorm(vmin=-.075,vcenter=0,vmax=.075)
B_NORM=TwoSlopeNorm(vmin=-.24,vcenter=0,vmax=.24)
DELTA_BAND=BAND_VALUES[...,1]-BAND_VALUES[...,0]
# Public alphabetical ordering is reused across Main5 and ED06; no rank sorting.
ORDER=[MODELS.index(m) for m in
       ["DeepSpot","DeepSpaCE","EGNv1","EGNv2","Hist2ST","HisToGene",
        "MLP","Ridge-Phikon-v2","ST-Net","THItoGene","TCGN"]]
NEW_MODELS=[MODELS[i] for i in ORDER]
X=np.array([0,1,2,3,4.22,5.22,6.22,7.44,8.44])
ENDPOINT_LABELS=["Fine-scale q\n(B4 + B5)/2","Broad-scale\ncorrelation, q","Overall Pearson r"]

def axmm(fig,x,y,w,h):
    return fig.add_axes([x/W,y/H,w/W,h/H],facecolor=PAPER)
def txt(fig,x,y,s,size=7,weight="regular",**kw):
    return fig.text(x/W,y/H,s,fontsize=size,fontweight=weight,color=kw.pop("color",INK),
                    va=kw.pop("va","top"),zorder=30,**kw)
def naked(ax):
    for spine in ax.spines.values():spine.set_visible(False)
    ax.tick_params(length=0,pad=1.8,colors=INK)
    ax.set_axisbelow(True)
def heading(fig,letter,y,label):
    txt(fig,3,y+.35,letter,9.2,"bold")
    txt(fig,34,y,label,8)
def tile(ax,x,y,v,norm,w=.94,h=.87,label=None,gid=None):
    p=Rectangle((x-w/2,y-h/2),w,h,fc=D_CMAP(norm(v)),ec=PAPER,lw=.38,zorder=2)
    p.set_gid(gid);ax.add_patch(p)
    if label is not None:
        # The strongest signed fields get white glyphs; all labels sit above marks.
        c=PAPER if abs(float(norm(v))-.5)>.36 else INK
        ax.text(x,y,label,ha="center",va="center",fontsize=7,color=c,zorder=30)
def cb(fig,x,y,w,norm,cmap,ticks,labels,label):
    ax=axmm(fig,x,y,w,1.8);naked(ax)
    edges=np.linspace(norm.vmin,norm.vmax,129)
    for a,b in zip(edges[:-1],edges[1:]):
        ax.add_patch(Rectangle((a,0),b-a,1,fc=cmap(norm((a+b)/2)),ec="none",zorder=2))
    ax.set(xlim=(norm.vmin,norm.vmax),ylim=(0,1),yticks=[])
    ax.set_xticks(ticks);ax.set_xticklabels(labels)
    ax.tick_params(axis="x",length=1.8,width=.45,pad=1)
    ax.set_xlabel(label,labelpad=1.2)
    for s in ax.spines.values():s.set_visible(True);s.set_color(INK);s.set_linewidth(.4)
    return ax

def fine_field(fig):
    heading(fig,"a",206,"Fine-scale q: neighbouring − non-neighbouring")
    field=axmm(fig,34,138.5,94,57.2);naked(field)
    margin=axmm(fig,132,138.5,30.5,57.2);naked(margin)
    field.set(xlim=(-.53,8.97),ylim=(10.5,-.5),xticks=[],yticks=range(11))
    field.set_yticklabels(NEW_MODELS)
    for yi,di in enumerate(ORDER):
        for si,v in enumerate(FINE_DELTA[di]):
            tile(field,X[si],yi,v,F_NORM,label=f"{v*1000:+.1f}",gid=f"a-specimen-{di}-{si}")
        mean,lo,hi=FINE_SUMMARY[di]
        col=TEAL if mean>=0 else BRICK
        margin.errorbar(mean,yi,xerr=np.array([[mean-lo],[hi-mean]]),fmt="D",
            ms=3.6,mfc=col,mec=PAPER,mew=.4,ecolor=col,elinewidth=.75,capsize=1.4,zorder=5)
        txt(fig,176,195.7-(yi+.5)*(57.2/11),f"{mean:+.4f}",ha="right",va="center")
    for a,b,name in [(0,3,"IDC"),(4,6,"PAAD"),(7,8,"Lung")]:
        field.plot([X[a]-.45,X[b]+.45],[-.83,-.83],color=TEAL,lw=.55,clip_on=False,zorder=3)
        field.text((X[a]+X[b])/2,-1.07,name,ha="center",va="bottom",
                   fontsize=7,color=INK,clip_on=False,zorder=30)
    margin.set(xlim=(-.025,.045),ylim=(10.5,-.5),yticks=[])
    margin.set_xticks([-.02,0,.04]);margin.set_xticklabels(["−0.02","0","+0.04"])
    margin.axvline(0,color=RULE,lw=.65,zorder=1)
    margin.spines["bottom"].set_visible(True)
    margin.spines["bottom"].set_color(INK);margin.spines["bottom"].set_linewidth(.5)
    margin.tick_params(axis="x",length=1.8,width=.45,pad=1)
    txt(fig,147.25,201.0,"Mean change in q",ha="center")
    return field,margin

def endpoint_field(fig):
    # The specimen coordinate is shared with a, avoiding a detached second page.
    heading(fig,"b",132.5,"Specimen means")
    ax=axmm(fig,34,110,94,17.2);naked(ax)
    ax.set(xlim=(-.53,8.97),ylim=(2.5,-.5),yticks=range(3))
    ax.set_yticklabels(ENDPOINT_LABELS,linespacing=.93)
    for ei in range(3):
        for si,v in enumerate(AGGREGATE_DELTA[ei]):
            tile(ax,X[si],ei,v,F_NORM,h=.86,label=f"{v*1000:+.1f}",gid=f"b-aggregate-{ei}-{si}")
        txt(fig,159.5,127.2-(ei+.5)*(17.2/3),f"{AGGREGATE_SUMMARY[ei,0]:+.4f}",
            ha="right",va="center",color=TEAL)
    txt(fig,152.5,131.5,"Mean",ha="center")
    ax.set_xticks(X)
    ax.set_xticklabels(SPECIMENS,rotation=55,ha="right",rotation_mode="anchor")
    ax.tick_params(axis="x",pad=2)
    cb(fig,73,91.5,55,F_NORM,D_CMAP,[-.075,0,.075],["−75","0","+75"],"Change in correlation (×1,000)")
    return ax

def old_atlas(fig):
    heading(fig,"c",80.0,"Scale-specific q: neighbouring pairs versus standard training")
    # Compact three-lane reference motif: square, circle, signed tile.
    leg=[
        Line2D([],[],marker="s",ls="none",ms=2.6,mfc=MID,mec=PAPER,mew=.2,label="Standard training"),
        Line2D([],[],marker="o",ls="none",ms=2.6,mfc=MID,mec=PAPER,mew=.2,label="Neighbouring pairs"),
        Line2D([],[],marker="s",ls="none",ms=4.2,mfc=MID,mec=PAPER,mew=.2,label="Change in q")]
    fig.legend(handles=leg,loc="upper left",bbox_to_anchor=(34/W,75.7/H),frameon=False,
        ncol=3,fontsize=7,handlelength=.7,handletextpad=.32,columnspacing=.95,borderpad=.02)
    ax=axmm(fig,34,23.5,111,43);naked(ax)
    am=axmm(fig,150,23.5,26,43);naked(am)
    mh,gap=3.0,.85
    for mi,m in enumerate(OLD_MODELS):
        yy=mi*mh
        ax.text(-.018,yy+1.15,m,transform=ax.get_yaxis_transform(),ha="right",va="center",zorder=30,fontsize=7)
        ax.axhline(yy+2.6,color=RULE,lw=.32,zorder=0)
        for bi in range(5):
            xs=bi*(9+gap)+np.arange(9)
            for arm,y,mk in [(0,yy+.40,"s"),(1,yy+1.18,"o")]:
                c=ax.scatter(xs,np.full(9,y),s=6.2,marker=mk,c=BAND_VALUES[mi,:,bi,arm],
                    cmap=Q_CMAP,norm=Q_NORM,edgecolors=PAPER,linewidths=.18,zorder=2)
                c.set_gid(f"c-absolute-{mi}-{bi}-{arm}")
            for si,v in enumerate(DELTA_BAND[mi,:,bi]):
                tile(ax,xs[si],yy+1.99,v,B_NORM,w=.86,h=.60,gid=f"c-band-{mi}-{bi}-{si}")
            v=DELTA_BAND[mi,:,bi].mean()
            tile(am,bi,mi,v,B_NORM,w=.91,h=.84,label=f"{v*1000:+.0f}",gid=f"c-band-mean-{mi}-{bi}")
    for bi,b in enumerate(SCALES):
        x0=bi*(9+gap)
        ax.plot([x0-.46,x0+8.46],[-.47,-.47],color=INK,lw=.45,clip_on=False)
        ax.text(x0+4,-.78,b,ha="center",va="bottom",fontsize=7.2,zorder=30)
        if bi:ax.axvline(x0-.84,color=RULE,lw=.5,zorder=0)
    ax.set(xlim=(-.56,4*(9+gap)+8.56),ylim=(23.75,-.18),yticks=[])
    ax.set_xticks([b*(9+gap)+s for b in range(5) for s in range(9)])
    ax.set_xticklabels([str(s+1) for b in range(5) for s in range(9)])
    ax.tick_params(axis="x",length=1.6,width=.4,pad=1.0)
    am.set(xlim=(-.5,4.5),ylim=(7.5,-.5),yticks=[],xticks=range(5))
    am.set_xticklabels(SCALES,rotation=65,ha="right",rotation_mode="anchor")
    am.tick_params(axis="x",pad=1)
    txt(fig,163,73.2,"Mean change in q",ha="center")
    txt(fig,163,69.8,"(×1,000)",ha="center")
    oldfine=BAND_VALUES[:,:,3:5,:].mean(axis=(0,1,2))
    txt(fig,34,16.5,f"Mean (B4 + B5)/2  {oldfine[0]:.4f} to {oldfine[1]:.4f}  ({oldfine[1]-oldfine[0]:+.4f})")
    cb(fig,39,8.3,54,Q_NORM,Q_CMAP,[-.15,0,.4,.8],["−0.15","0","0.40","0.80"],"Noise-corrected correlation, q")
    cb(fig,116,8.3,60,B_NORM,D_CMAP,[-.24,0,.24],["−0.24","0","+0.24"],"Change in q (neighbouring − standard)")
    return ax,am

def floor_check(fig,path):
    texts=[t for t in fig.findobj(Text) if t.get_visible() and t.get_text().strip()]
    for t in texts:t.set_zorder(30)
    for l in fig.legends:l.set_zorder(28)
    fig.canvas.draw();renderer=fig.canvas.get_renderer()
    items=[(t,t.get_window_extent(renderer)) for t in texts]
    clips=[t.get_text() for t,b in items if b.width and b.height and
       (b.x0<0 or b.y0<0 or b.x1>fig.bbox.width or b.y1>fig.bbox.height)]
    overlaps=[(a.get_text(),b.get_text()) for i,(a,ba) in enumerate(items)
      for b,bb in items[i+1:] if ba.width and ba.height and bb.width and bb.height and ba.overlaps(bb)]
    gids=[a.get_gid() for ax in fig.axes for a in ax.get_children() if a.get_gid()]
    checks={
      "99 specimen differences rendered exactly once":sum(str(g).startswith("a-specimen-") for g in gids)==99,
      "11 source means and paired-difference CIs":FINE_SUMMARY.shape==(11,3),
      "27 equal-model specimen aggregates":sum(str(g).startswith("b-aggregate-") for g in gids)==27,
      "360 old paired band changes":sum(str(g).startswith("c-band-") and not str(g).startswith("c-band-mean") for g in gids)==360,
      "720 old correlation-value glyphs":BAND_VALUES.shape==(8,9,5,2),
      "40 old model-band means":sum(str(g).startswith("c-band-mean") for g in gids)==40,
      "all fine means equal frozen source":np.allclose(FINE_DELTA.mean(1),FINE_SUMMARY[:,0],atol=1e-14),
      "three endpoint means equal frozen source":np.allclose(AGGREGATE_DELTA.mean(1),AGGREGATE_SUMMARY[:,0],atol=1e-14),
      "adverse outcomes retain signed magnitudes":np.min(FINE_DELTA)<0 and np.min(AGGREGATE_DELTA[1:])<0,
      "unclipped data scales":np.max(np.abs(FINE_DELTA))<.075 and np.max(np.abs(DELTA_BAND))<.24,
      "q decimal units without percent scaling":not any("%" in t.get_text() for t in texts),
      "minimum source font 7 pt":min(t.get_fontsize() for t in texts)>=7,
      "text clipping":not clips,"text overlap":not overlaps,
    }
    lines=["Figure 5 iteration 0; 180 x 210 mm",
      "Difference zero is white; teal/brick encode continuous signed magnitude.",
      "text_obscured_by_marks: PASS (text z-order 30; data 0-5; strong field text reversed).",
      "Main5 direct-ordering detail transferred to ED06 d/e without deleting source records.",
      "Old fine=(B4+B5)/2 and new mean_q_B4_B5 retain distinct comparisons/denominators.",
      "No new bootstrap, arm CI, pooled biological unit, or data interpolation.",
      f"Visible texts: {len(texts)}; overlaps: {len(overlaps)}; clipped: {len(clips)}.",
      "Rendered geometry: new field 94 x 57.2 mm, row pitch 5.2 mm; 4 mm gap to effect margin.",
      "Rendered geometry: old atlas 111 x 43 mm; 5 mm gap to mean-band margin.",
    ]+[k+": "+("PASS" if v else "FAIL") for k,v in checks.items()]
    lines+=["OVERLAP "+repr(x) for x in overlaps]+["CLIPPED "+x for x in clips]
    lines+=["OVERALL: "+("PASS" if all(checks.values()) else "FAIL")]
    path.write_text("\n".join(lines)+"\n",encoding="utf-8")
    return all(checks.values())

def main():
    out=Path(__file__).resolve().parent
    fig=plt.figure(figsize=(W/25.4,H/25.4),dpi=180,facecolor=PAPER)
    fine_field(fig);endpoint_field(fig);old_atlas(fig)
    ok=floor_check(fig,out/"floor_selfcheck_iter0.txt")
    fig.savefig(out/"img_iter0.png",dpi=360,facecolor=PAPER,edgecolor="none")
    fig.savefig(out/"figure_iter0.pdf",facecolor=PAPER,edgecolor="none")
    fig.savefig(out/"Figure6.svg",facecolor=PAPER,edgecolor="none")
    plt.close(fig)
    print("Wrote Figure5 iteration 0; floor="+("PASS" if ok else "FAIL"))
    if not ok:raise SystemExit(1)
if __name__=="__main__":main()
